package ca.humber.alerts;import org.springframework.context.annotation.*;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.*;import org.springframework.security.provisioning.InMemoryUserDetailsManager;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.web.SecurityFilterChain;@Configuration public class AlertSecurity {@Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{return http.csrf(csrf->csrf.disable()).authorizeHttpRequests(a->a.anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}@Bean UserDetailsService accounts(@org.springframework.beans.factory.annotation.Value("${alerts.user:bridge}")String user,@org.springframework.beans.factory.annotation.Value("${alerts.password:bridge-dev-password}")String password){return new InMemoryUserDetailsManager(User.withUsername(user).password(new BCryptPasswordEncoder().encode(password)).roles("SERVICE").build());}}